import React, { useLayoutEffect, useRef, useState, useCallback } from 'react';
import { Join, Point } from '../types';

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

interface LinePosition {
  id: string;
  p1: Point;
  p2: Point;
  join: Join;
}

interface JoinLinesProps {
  joins: Join[];
  drawingLine: { start: Point; end: Point } | null;
  hoveredJoinId: string | null;
  cardPositions: Record<string, Point>;
  draggedTable: string | null;
}

const JoinLines: React.FC<JoinLinesProps> = ({ joins, drawingLine, hoveredJoinId, cardPositions, draggedTable }) => {
  const [linePositions, setLinePositions] = useState<LinePosition[]>([]);
  const animatedPositionsRef = useRef<Record<string, { p1: Point; p2: Point }>>({});

  // Use fixed positioning relative to viewport to avoid scroll sync lag issues
  const getTargetPositions = useCallback(() => {
    const targets: Record<string, { p1: Point; p2: Point; join: Join }> = {};

    joins.forEach(join => {
      const el1 = document.getElementById(`col-${join.table1}-${join.column1}`);
      const el2 = document.getElementById(`col-${join.table2}-${join.column2}`);

      if (el1 && el2) {
        const rect1 = el1.getBoundingClientRect();
        const rect2 = el2.getBoundingClientRect();

        // Coordinates are now strictly viewport-relative
        const p1 = {
          x: rect1.left + rect1.width, // Right edge of source
          y: rect1.top + rect1.height / 2,
        };
        const p2 = {
          x: rect2.left, // Left edge of target
          y: rect2.top + rect2.height / 2,
        };
        targets[join.id] = { p1, p2, join };
      }
    });
    return targets;
  }, [joins]);

  useLayoutEffect(() => {
    let animationFrameId: number;

    const animate = () => {
      // Only compute if we have joins to draw
      if (joins.length === 0) {
        if (linePositions.length > 0) setLinePositions([]);
        animationFrameId = requestAnimationFrame(animate);
        return;
      }

      const targets = getTargetPositions();
      const currentAnimated = animatedPositionsRef.current;

      // Initialize or update animated positions
      for (const id in targets) {
        if (!currentAnimated[id]) {
          currentAnimated[id] = { p1: targets[id].p1, p2: targets[id].p2 };
        }

        currentAnimated[id].p1.x = lerp(currentAnimated[id].p1.x, targets[id].p1.x, 0.25);
        currentAnimated[id].p1.y = lerp(currentAnimated[id].p1.y, targets[id].p1.y, 0.25);
        currentAnimated[id].p2.x = lerp(currentAnimated[id].p2.x, targets[id].p2.x, 0.25);
        currentAnimated[id].p2.y = lerp(currentAnimated[id].p2.y, targets[id].p2.y, 0.25);
      }

      // Garbage collect deleted joins
      for (const id in currentAnimated) {
          if (!targets[id]) {
              delete currentAnimated[id];
          }
      }

      const newPositions = Object.keys(currentAnimated).map(id => {
        const points = currentAnimated[id];
        return {
            id,
            p1: points.p1,
            p2: points.p2,
            join: joins.find(j => j.id === id)!,
        };
      }).filter(p => p.join);

      setLinePositions(newPositions);
      animationFrameId = requestAnimationFrame(animate);
    };

    animationFrameId = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [joins, cardPositions, getTargetPositions]);

  return (
    <svg className="fixed top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 5 }}>
      <defs>
        <linearGradient id="line-gradient" x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="#5856D6" />
          <stop offset="100%" stopColor="#007AFF" />
        </linearGradient>
        <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="3.5" result="coloredBlur" in="SourceGraphic" />
            <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
            </feMerge>
        </filter>
      </defs>

      {linePositions.map(({ id, p1, p2, join }) => {
        const isHot = id === hoveredJoinId || join.table1 === draggedTable || join.table2 === draggedTable;
        const dx = Math.abs(p2.x - p1.x) * 0.5;
        const pathData = `M ${p1.x} ${p1.y} C ${p1.x + dx} ${p1.y}, ${p2.x - dx} ${p2.y}, ${p2.x} ${p2.y}`;

        return (
          <g key={id} className="transition-all duration-200" style={{ filter: isHot ? 'url(#glow)' : 'none' }}>
            <path
              d={pathData}
              stroke="url(#line-gradient)"
              strokeWidth={isHot ? 3.5 : 2}
              strokeOpacity={isHot ? 1 : 0.6}
              fill="none"
              className="transition-all duration-200"
            />
            <circle cx={p1.x} cy={p1.y} r={isHot ? 5 : 3.5} fill="white" stroke={isHot ? "#5856D6" : "#007AFF"} strokeWidth="1.5" />
            <circle cx={p2.x} cy={p2.y} r={isHot ? 5 : 3.5} fill="white" stroke={isHot ? "#007AFF" : "#5856D6"} strokeWidth="1.5" />
          </g>
        );
      })}

      {drawingLine && (
        <path
          d={`M ${drawingLine.start.x} ${drawingLine.start.y} C ${drawingLine.start.x + 40} ${drawingLine.start.y}, ${drawingLine.end.x - 40} ${drawingLine.end.y}, ${drawingLine.end.x} ${drawingLine.end.y}`}
          stroke="#5856d6"
          strokeWidth="2"
          strokeDasharray="6 6"
          fill="none"
        />
      )}
    </svg>
  );
};

export default JoinLines;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { ColumnSchema, Point } from '../types';
import { Table2, GripVertical } from 'lucide-react';
import DataTypeIcon from './DataTypeIcon';

interface InteractiveSchemaCardProps {
  tableName: string;
  displayName: string;
  schema: ColumnSchema[];
  position: Point;
  onDrag: (tableName: string, newPosition: Point) => void;
  onDragStart?: (tableName: string) => void;
  onDragEnd?: () => void;
  onColumnMouseDown: (tableName: string, columnName: string) => void;
  onColumnMouseUp: (tableName: string, columnName: string) => void;
  onColumnEnter: (target: { table: string, column: string } | null) => void;
  onColumnLeave: () => void;
  isSource: boolean;
  sourceColumn: string | null;
  compatibleTargets: Set<string>;
  activeJoinColumns: Set<string>;
}

const InteractiveSchemaCard: React.FC<InteractiveSchemaCardProps> = React.memo(({
  tableName,
  displayName,
  schema,
  position,
  onDrag,
  onDragStart,
  onDragEnd,
  onColumnMouseDown,
  onColumnMouseUp,
  onColumnEnter,
  onColumnLeave,
  isSource,
  sourceColumn,
  compatibleTargets,
  activeJoinColumns,
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const dragStartPos = useRef<Point>({ x: 0, y: 0 });
  const offsetRef = useRef<Point>({ x: 0, y: 0 });

  // Refs to hold current listeners so we can remove them in cleanup
  const mouseMoveListenerRef = useRef<((e: MouseEvent) => void) | null>(null);
  const mouseUpListenerRef = useRef<((e: MouseEvent) => void) | null>(null);

  const cleanupListeners = useCallback(() => {
    if (mouseMoveListenerRef.current) {
      window.removeEventListener('mousemove', mouseMoveListenerRef.current);
      mouseMoveListenerRef.current = null;
    }
    if (mouseUpListenerRef.current) {
      window.removeEventListener('mouseup', mouseUpListenerRef.current);
      mouseUpListenerRef.current = null;
    }
  }, []);

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    onDragStart?.(tableName);
    dragStartPos.current = {
      x: e.clientX,
      y: e.clientY,
    };

    const handleMouseMove = (moveEvent: MouseEvent) => {
      setIsDragging(true);
      offsetRef.current = {
          x: moveEvent.clientX - dragStartPos.current.x,
          y: moveEvent.clientY - dragStartPos.current.y,
      };
      // Force render for smooth drag
      setIsDragging(prev => prev); 
    };

    const handleMouseUp = (upEvent: MouseEvent) => {
      const finalPosition = {
        x: position.x + (upEvent.clientX - dragStartPos.current.x),
        y: position.y + (upEvent.clientY - dragStartPos.current.y),
      };
      onDrag(tableName, finalPosition);

      setIsDragging(false);
      offsetRef.current = { x: 0, y: 0 };
      cleanupListeners();
      onDragEnd?.();
    };

    mouseMoveListenerRef.current = handleMouseMove;
    mouseUpListenerRef.current = handleMouseUp;

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
  }, [position, onDrag, tableName, onDragStart, onDragEnd, cleanupListeners]);

  // Clean up listeners if component unmounts while dragging
  useEffect(() => {
      return () => {
          cleanupListeners();
      }
  }, [cleanupListeners]);

  const currentPosition = {
    left: position.x + (isDragging ? offsetRef.current.x : 0),
    top: position.y + (isDragging ? offsetRef.current.y : 0),
  };

  return (
    <div
      className={`absolute bg-card/80 backdrop-blur-xl border border-white/20 rounded-xl shadow-lg w-72 flex flex-col transition-shadow duration-200 hover:shadow-xl hover:scale-[1.02] select-none`}
      style={{
        left: currentPosition.left,
        top: currentPosition.top,
        cursor: isDragging ? 'grabbing' : 'default',
        zIndex: isDragging ? 50 : (activeJoinColumns.size > 0 ? 40 : 10),
        boxShadow: activeJoinColumns.size > 0 ? '0 0 20px 5px rgba(0, 122, 255, 0.25)' : undefined,
        transition: isDragging ? 'none' : 'all 0.2s',
      }}
    >
      <div
        className="flex items-center gap-2 p-3 border-b border-black/5"
        onMouseDown={handleMouseDown}
        style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
      >
        <GripVertical size={18} className="text-text-secondary/50" />
        <Table2 size={16} className="text-text" />
        <h3 className="font-semibold text-md text-text truncate flex-1" title={displayName}>
          {displayName}
        </h3>
      </div>
      <div className="space-y-1 p-2 flex-1 overflow-y-auto max-h-[220px]">
        {schema.map((col) => {
          const isCompatible = compatibleTargets.has(`${tableName}-${col.name}`);
          const isActiveJoin = activeJoinColumns.has(`${tableName}-${col.name}`);
          const isSourceCol = isSource && sourceColumn === col.name;

          return (
            <div
              key={col.name}
              id={`col-${tableName}-${col.name}`}
              className={`flex justify-between items-center text-sm p-1.5 rounded-md transition-all duration-150 relative group ${
                isSourceCol ? 'bg-primary/20' : ''
              } ${
                isActiveJoin ? 'bg-primary/20 font-semibold' : ''
              }`}
              onMouseDown={(e) => {
                  // Only allow starting a join drag from the right edge of the column item
                  if (e.currentTarget.clientWidth - e.nativeEvent.offsetX < 30) {
                      e.preventDefault(); 
                      e.stopPropagation(); 
                      onColumnMouseDown(tableName, col.name);
                  }
              }}
              onMouseUp={() => onColumnMouseUp(tableName, col.name)}
              onMouseEnter={() => onColumnEnter({ table: tableName, column: col.name })}
              onMouseLeave={onColumnLeave}
            >
              <div className="flex items-center gap-2 overflow-hidden pointer-events-none">
                  <DataTypeIcon type={col.type} />
                  <span className="text-text font-medium truncate pr-2">{col.name}</span>
              </div>
              <div 
                className="w-3 h-3 bg-secondary-background border-2 border-primary/50 rounded-full right-2 absolute opacity-0 group-hover:opacity-100 transition-opacity hover:scale-125 hover:bg-primary hover:border-white cursor-crosshair"
                title="Drag to connect"
              ></div>
              {isCompatible && <div className="absolute inset-0 rounded-md animate-pulse-glow pointer-events-none border border-primary/50"></div>}
            </div>
          );
        })}
        {schema.length === 0 && <span className="text-xs text-text-secondary p-2">No columns found.</span>}
      </div>
    </div>
  );
});

export default InteractiveSchemaCard;

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { LLMProvider } from './base';
import { SQLGenerationResult, ChartGenerationResult, TableSchema, InsightGenerationResult, ChartGenerationWithMetadataResult, Join, Correction } from '../../types';
import { LLMGenerationError } from '../../utils/exceptions';
import { config } from '../../config';
import { enhancePromptWithSchemaAwareness } from '../../utils/promptEnhancer';

// Type alias to handle potential legacy 'dataKey' property for backward compatibility.
type ParsedChartConfig = ChartGenerationResult & { dataKey?: string };
export class GeminiProvider extends LLMProvider {
  private ai: GoogleGenAI;

  constructor() {
    super();
    this.ai = new GoogleGenAI({ apiKey: config.apiKey });
  }

  private calculateCost(model: string, promptTokens: number, completionTokens: number): number {
    const pricing = config.llmPricing[model];
    if (!pricing) return 0;
    const promptCost = (promptTokens / 1_000_000) * pricing.prompt;
    const completionCost = (completionTokens / 1_000_000) * pricing.completion;
    return promptCost + completionCost;
  }

  async generateSQL(prompt: string, schemas: TableSchema, dialect: string, history: { role: string, content: string }[], dataPreview?: Record<string, Record<string, any>[]>, joins?: Join[], corrections?: Correction[]): Promise<SQLGenerationResult> {
    const allColumns = Object.values(schemas).flat().map(col => col.name);
    const typoCorrections = enhancePromptWithSchemaAwareness(prompt, allColumns);

    let correctedQuestion = prompt;
    let correctionHint = "";

    if (Object.keys(typoCorrections).length > 0) {
        const hints = Object.entries(typoCorrections).map(([t, c]) => `'${t}'->'${c}'`).join(", ");
        correctionHint = `\nHINT: The user may have made typos. Apply these corrections: ${hints}.`;

        Object.entries(typoCorrections).forEach(([typo, correct]) => {
            correctedQuestion = correctedQuestion.replace(new RegExp(`\\b${typo}\\b`, 'gi'), correct);
        });
    }

    const schemasStr = Object.entries(schemas)
      .map(([name, cols]) => `- Table '${name}' columns: [${cols.map(c => `${c.name} (${c.type})`).join(', ')}]`)
      .join('\n');

    let previewStr = "";
    if (dataPreview && Object.keys(dataPreview).length > 0) {
        previewStr = "\nHere are some sample rows from the tables:\n";
        for (const [tableName, rows] of Object.entries(dataPreview)) {
            if (rows.length > 0) {
                const headers = Object.keys(rows[0]);
                const rowsStr = rows.map(row => 
                    headers.map(h => String(row[h])).join(', ')
                ).join('\n');
                previewStr += `- Table '${tableName}' sample data (columns: ${headers.join(', ')}):\n${rowsStr}\n`;
            }
        }
    }

    let joinInstruction = "";
    if (joins && joins.length > 0) {
        const joinClauses = joins.map(j => 
            `- Use a ${j.joinType.toUpperCase()} JOIN between table [${j.table1}] and [${j.table2}] ON [${j.table1}].[${j.column1}] = [${j.table2}].[${j.column2}]`
        ).join('\n');
        joinInstruction = `When querying across multiple tables, you MUST adhere to the following user-defined join conditions:\n${joinClauses}`;
    } else if (Object.keys(schemas).length > 1) {
        joinInstruction = "- If the user's question requires joining tables, intelligently infer the join columns based on column names and relationships. Explicitly state the join condition in the SQL query (e.g., `FROM table1 JOIN table2 ON table1.id = table2.foreign_id`)."
    }

    let dialectSpecificInstruction = "";
    if (dialect === 'alasql') {
        dialectSpecificInstruction = `- IMPORTANT: For the 'alasql' dialect, you MUST adhere to these critical rules:
  - Enclose any column or table name containing spaces or special characters in square brackets (e.g., \`SELECT [Customer Id] FROM [Order Details]\`).
  - **You MUST NOT use window functions**. Functions like \`LAG()\`, \`LEAD()\`, \`ROW_NUMBER()\`, \`RANK()\`, or any function that uses an \`OVER()\` clause are NOT supported. For complex calculations like year-over-year growth, you must use alternative methods such as self-joins.`;
    }

    let userCorrectionsStr = "";
    if (corrections && corrections.length > 0) {
      userCorrectionsStr = `
---
LEARNING FROM USER FEEDBACK:
The user has provided corrections in the past. These represent the ground truth for how to query their data. Prioritize these patterns.
${corrections.map((c, i) => `
## Correction ${i + 1}
User Question: "${c.question}"
Correct SQL: ${c.sql}
`).join('\n')}
---
`;
    }

    const fewShotExamples = `
---
Here are some examples of how to map questions to SQL queries. Adapt these patterns to the provided schema.

## Basic Aggregation
Question: "total sales for each product"
SQL: SELECT product_column, SUM(sales_column) FROM table_name GROUP BY product_column;

## Filtering
Question: "employees in the 'Sales' department"
SQL: SELECT * FROM employee_table WHERE department_column = 'Sales';

## Joining
Question: "sales in 'North America' and their sales reps"
SQL: SELECT t1.product, t1.sales, t2.employee_name FROM sales_table t1 JOIN employee_table t2 ON t1.region_key = t2.region_key WHERE t1.region_key = 'North America';

## Data Enrichment with General Knowledge (CTE and CASE)
Question: "what is the distribution of orders by continent" (given a table with a 'country' column but no 'continent' column)
SQL: WITH enriched_orders AS (
  SELECT
    *,
    CASE
      WHEN country IN ('United States', 'Canada', 'Mexico') THEN 'North America'
      WHEN country IN ('United Kingdom', 'Germany', 'France', 'Italy', 'Spain') THEN 'Europe'
      WHEN country IN ('China', 'India', 'Japan', 'South Korea') THEN 'Asia'
      WHEN country IN ('Brazil', 'Argentina', 'Colombia') THEN 'South America'
      WHEN country IN ('Nigeria', 'Egypt', 'South Africa') THEN 'Africa'
      WHEN country IN ('Australia', 'New Zealand') THEN 'Oceania'
      ELSE 'Other'
    END AS continent
  FROM orders
)
SELECT
  continent,
  COUNT(order_id) AS number_of_orders
FROM enriched_orders
WHERE continent IS NOT NULL
GROUP BY
  continent
ORDER BY
  number_of_orders DESC;
---
`;

    const systemPrompt = `You are a precise, world-class SQL generator. Your sole purpose is to translate a natural language question into a single, valid SQL query for the ${dialect} dialect.
Constraints:
- Return ONLY the raw SQL query. Do not include explanations, comments, or markdown formatting like \`\`\`sql.
- Your entire response must be only the SQL query.
- Always qualify columns with table names or aliases (e.g., \`sales.product\`).
- If the question asks for a metric "by" or "for each" of a certain category (e.g., "sales by region", "count of users per country"), you MUST use a GROUP BY clause.
- **Intelligent Data Enrichment**: You MUST use your general world knowledge to enrich the data. If a question requires a column that is not in the schema but can be logically derived from existing columns (e.g., deriving 'continent' from a 'country' column, or 'day_of_week' from a 'date' column), you MUST generate SQL that creates this new column on the fly, typically using a Common Table Expression (CTE) with a CASE statement.
- Never hallucinate tables or columns that are not present in the provided schema.
- If the question is ambiguous, choose the most conservative interpretation.
- Return at most 1000 rows unless the user specifies a different limit.
${dialectSpecificInstruction}
${joinInstruction}
${userCorrectionsStr}
${fewShotExamples}
Schema:
${schemasStr}
${previewStr}
${correctionHint}`;

    const historyStr = history.map(h => {
        return h.role === 'user' 
            ? `PREVIOUS QUESTION: "${h.content}"`
            : `PREVIOUS SQL:\n${h.content}`;
    }).join('\n\n');

    const currentQuestionStr = `--- Current Question ---\nBased on the conversation so far, generate a SQL query for this question: ${prompt}`;

    const contentsPayload = `${systemPrompt}\n\n${historyStr ? `--- Conversation History ---\n${historyStr}\n\n` : ''}${currentQuestionStr}`;

    try {
      const modelName = 'gemini-2.5-flash';

      const response: GenerateContentResponse = await this.ai.models.generateContent({
        model: modelName,
        contents: contentsPayload,
      });

      let sqlQuery = response.text.replace(/```sql/g, '').replace(/```/g, '').trim();
      // Clean up potentially leaked markdown if logic above misses it
      sqlQuery = sqlQuery.replace(/^```/, '').replace(/```$/, '').trim();

      const promptTokens = response.usageMetadata?.promptTokenCount ?? 0;
      const completionTokens = response.usageMetadata?.candidatesTokenCount ?? 0;
      const cost = this.calculateCost(modelName, promptTokens, completionTokens);

      return {
        sql: sqlQuery,
        correctedQuestion: correctedQuestion,
        model: modelName,
        cost: cost,
        prompt_tokens: promptTokens,
        completion_tokens: completionTokens,
      };
    } catch (e: any) {
      let errorMessage = "I couldn't generate SQL for that. Please try rephrasing your question in plain English.";
      if (typeof e.message === 'string') {
          if (e.message.includes('API key not valid')) {
              errorMessage = 'The configured Gemini API key is invalid or missing. Please contact the administrator.';
          } else if (e.message.toLowerCase().includes('quota')) {
              errorMessage = 'The API usage limit has been reached. Please contact the administrator.';
          }
      }
      throw new LLMGenerationError(errorMessage);
    }
  }

  async generateInsights(question: string, data: Record<string, any>[]): Promise<InsightGenerationResult> {
    const dataPreview = JSON.stringify(data.slice(0, 50), null, 2);

    const systemInstruction = `You generate a crisp, factual summary of a query result for a business audience.
- Explain the key pattern in 5 sentences or less.
- Use column names and units; avoid speculation.
- If the result might be truncated (e.g., has 50 rows), mention that the data is a sample.
- Use markdown for formatting (e.g., lists, bold text).`;

    const userPrompt = `Context: The user asked "${question}".\nResult sample (first 50 rows):\n${dataPreview}`;

    const contentsPayload = `${systemInstruction}\n\n${userPrompt}`;

    try {
      const modelName = 'gemini-2.5-flash';

      const response = await this.ai.models.generateContent({
        model: modelName,
        contents: contentsPayload,
      });

      const promptTokens = response.usageMetadata?.promptTokenCount ?? 0;
      const completionTokens = response.usageMetadata?.candidatesTokenCount ?? 0;
      const cost = this.calculateCost(modelName, promptTokens, completionTokens);

      return {
        insights: response.text || "No insights generated.",
        model: modelName,
        cost: cost,
        prompt_tokens: promptTokens,
        completion_tokens: completionTokens,
      };
    } catch (e: any) {
      throw new LLMGenerationError(`Gemini insight generation failed: ${e.message}`);
    }
  }

  async generateChart(question: string, data: Record<string, any>[]): Promise<ChartGenerationWithMetadataResult> {
    if (data.length === 0 || Object.keys(data[0]).length < 2) {
        return {
            chartConfig: null,
            model: 'N/A',
            cost: 0,
            prompt_tokens: 0,
            completion_tokens: 0,
        };
    }
    const columns = Object.keys(data[0]);
    const dataPreview = JSON.stringify(data.slice(0, 5), null, 2);
    const modelName = "gemini-2.5-flash";

    const systemPrompt = `You are a world-class data visualization expert. Your task is to analyze a user's question and a dataset to determine the single best chart representation.
- User's question: "${question}"
- Available columns: ${columns.join(', ')}
- Data preview: ${dataPreview}

CHART SELECTION GUIDELINES:
- Time-series Trend: If the data has a clear time component (e.g., columns named 'date', 'day', 'month', 'year'), prefer 'line' or 'area' charts to show trends over time.
- Categorical Comparison: To compare values across different categories, use 'bar'.
- Proportional Composition: To show parts of a whole for a single metric across categories, use 'pie'. Only use a pie chart for 2-7 categories.
- Multi-Metric Comparison: If there are multiple numeric columns to compare against a single category, use 'composed' (e.g., bar for one metric, line for another) or 'stackedBar'.
- Correlation: If the goal is to see the relationship between two numeric variables, use 'scatter'.

OUTPUT REQUIREMENTS:
- Your output must be a single, valid JSON object with no other text or formatting.
- The JSON must conform to the provided schema.
- 'dataKeys' should contain a single element for simple charts (bar, line, area, pie). For 'composed' or 'stackedBar', it can contain multiple keys.
- For 'composed' charts, the 'composedTypes' array must have the same number of elements as 'dataKeys', specifying the chart type for each key.
- The 'title' should be a concise and descriptive title for the chart.`;

    const userPrompt = "Generate the chart configuration JSON for the provided context.";

    const contentsPayload = `${systemPrompt}\n\n${userPrompt}`;

    try {
        const response = await this.ai.models.generateContent({
            model: modelName,
            contents: contentsPayload,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        chartType: { type: Type.STRING, enum: ['bar', 'line', 'pie', 'scatter', 'area', 'composed', 'stackedBar'], description: 'The type of chart to render.' },
                        dataKeys: { type: Type.ARRAY, items: { type: Type.STRING }, description: 'Column names for the primary metrics (Y-axis). Single item for simple charts, multiple for composed/stacked.' },
                        nameKey: { type: Type.STRING, description: 'The column name for the category or label (X-axis or pie label).' },
                        title: { type: Type.STRING, description: 'A descriptive title for the chart.' },
                        composedTypes: {
                            type: Type.ARRAY,
                            nullable: true,
                            items: { type: Type.STRING, enum: ['bar', 'line', 'area'] },
                            description: "For 'composed' charts, specifies the type for each dataKey. Must match `dataKeys` length."
                        }
                    },
                    required: ["chartType", "dataKeys", "nameKey", "title"]
                },
            },
        });

      let jsonStr = response.text.trim();

      // Robust JSON extraction using regex to handle arbitrary text wrapping
      // This regex handles markdown code blocks with or without the 'json' language specifier
      const jsonMatch = jsonStr.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
          jsonStr = jsonMatch[0];
      } else {
          // Fallback cleanup if regex misses (unlikely but safe)
          jsonStr = jsonStr.replace(/^```(json)?/gm, "").replace(/```$/gm, "");
      }

      if (!jsonStr) {
          throw new Error("Generated response is empty or invalid.");
      }

      const chartConfig = JSON.parse(jsonStr) as ParsedChartConfig;
      const promptTokens = response.usageMetadata?.promptTokenCount ?? 0;
      const completionTokens = response.usageMetadata?.candidatesTokenCount ?? 0;
      const cost = this.calculateCost(modelName, promptTokens, completionTokens);

      // Backwards compatibility for models that might still return dataKey
      if (chartConfig.dataKey && !chartConfig.dataKeys) {
        chartConfig.dataKeys = [chartConfig.dataKey];
        delete chartConfig.dataKey;
      }

      return {
        chartConfig,
        model: modelName,
        cost,
        prompt_tokens: promptTokens,
        completion_tokens: completionTokens
      };
    } catch (e: any) {
      console.error("Chart generation failed, returning null.", e)
      return {
          chartConfig: null,
          model: modelName,
          cost: 0,
          prompt_tokens: 0,
          completion_tokens: 0,
      };
    }
  }
}

import React, { useState, useMemo, useEffect, useRef, useId } from 'react';
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
    PieChart, Pie, Cell, LineChart, Line, AreaChart, Area, ComposedChart
} from 'recharts';
import { NameType, ValueType } from 'recharts/types/component/DefaultTooltipContent';
import ReactMarkdown from 'react-markdown';
import { ConversationTurn, ChartGenerationResult } from '../types';
import { Table, BarChart2, Lightbulb, ChevronLeft, ChevronRight, Loader2, FileDown, FileText, Printer, FileImage, Check, X } from 'lucide-react';

interface ResultsDisplayProps {
  turn: ConversationTurn;
  onGenerateInsights: (turnId: string) => void;
  onGenerateChart: (turnId: string) => void;
}

type Tab = 'table' | 'insights' | 'chart';
const ROWS_PER_PAGE = 50;
const PALETTE = ['#007AFF', '#34C759', '#FF9500', '#FF3B30', '#5856D6', '#AF52DE'];

// The TooltipProps for a custom tooltip's content are not the same as the props for the Tooltip component.
// Defining a specific interface for the content renderer's props resolves potential type errors.
interface CustomTooltipProps {
  active?: boolean;
  payload?: {
    name: NameType;
    value: ValueType;
    color?: string;
  }[];
  label?: string | number;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/80 backdrop-blur-lg p-3 border border-black/10 rounded-xl shadow-2xl animate-scale-in text-text">
        <p className="font-bold text-sm mb-2 text-text">{label}</p>
        {payload.map((pld, index: number) => (
            <div key={index} className="flex justify-between items-center text-sm font-medium my-1 gap-4">
                <div className="flex items-center" style={{ color: pld.color }}>
                    <div className="w-2.5 h-2.5 rounded-full mr-2" style={{ backgroundColor: pld.color }}/>
                    <span>{pld.name}</span>
                </div>
                <span className="font-bold text-text">{pld.value?.toLocaleString()}</span>
            </div>
        ))}
      </div>
    );
  }
  return null;
};

const MetadataDisplay: React.FC<{
  label: string;
  model: string;
  cost: number;
  prompt_tokens: number;
  completion_tokens: number;
}> = ({ label, model, cost, prompt_tokens, completion_tokens }) => {
  const totalTokens = prompt_tokens + completion_tokens;
  if (model === 'N/A' && totalTokens === 0) return null;

  return (
    <div className="text-right text-xs text-text-secondary space-x-3 flex items-center justify-end flex-wrap">
      <span className="font-semibold text-text">{label}:</span>
      <span>Model: <b className="text-text">{model}</b></span>
      <span>Tokens: <b className="text-text">{totalTokens.toLocaleString()}</b></span>
      <span>Cost: <b className="text-text">${cost.toFixed(6)}</b></span>
    </div>
  );
};

const ChartControls: React.FC<{
    config: ChartGenerationResult;
    setConfig: React.Dispatch<React.SetStateAction<ChartGenerationResult | null>>;
    numericColumns: string[];
    categoricalColumns: string[];
    allColumns: string[];
}> = ({ config, setConfig, numericColumns, categoricalColumns, allColumns }) => {

    const handleChartTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const newType = e.target.value as ChartGenerationResult['chartType'];
        setConfig(prev => {
            if (!prev) return null;
            let newDataKeys = prev.dataKeys;
            // When switching to a single-series chart, keep only the first key.
            if (['pie', 'bar', 'line', 'area', 'scatter'].includes(newType) && prev.dataKeys.length > 1) {
                newDataKeys = [prev.dataKeys[0]];
            }
            // When switching to a multi-series chart, ensure at least one key exists.
            if (['composed', 'stackedBar'].includes(newType) && prev.dataKeys.length === 0 && numericColumns.length > 0) {
                 newDataKeys = [numericColumns[0]];
            }
            return { ...prev, chartType: newType, dataKeys: newDataKeys };
        });
    };

    const handleXAxisChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        setConfig(prev => prev ? { ...prev, nameKey: e.target.value } : null);
    };

    const handleYAxisChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        setConfig(prev => prev ? { ...prev, dataKeys: [e.target.value] } : null);
    };

    const handleMultiYAxisChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { value: column, checked } = e.target;
        setConfig(prev => {
            if (!prev) return null;
            const currentKeys = prev.dataKeys || [];
            const newKeys = checked ? [...currentKeys, column] : currentKeys.filter(key => key !== column);
            return { ...prev, dataKeys: newKeys };
        });
    };

    const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setConfig(prev => prev ? { ...prev, title: e.target.value } : null);
    };

    const xAxisOptions = useMemo(() => {
        if (config.chartType === 'scatter') return numericColumns;
        if (config.chartType === 'pie') return categoricalColumns;
        return allColumns;
    }, [config.chartType, numericColumns, categoricalColumns, allColumns]);

    const controlClass = "w-full p-2 text-sm border border-input rounded-md focus:ring-1 focus:ring-ring focus:outline-none transition bg-card";
    const isMultiSeries = config.chartType === 'stackedBar' || config.chartType === 'composed';

    return (
        <div className="p-3 bg-secondary-background/70 border-b border-black/5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 items-start">
            <div className="space-y-1">
                 <label className="block text-xs font-medium text-text-secondary">Chart Title</label>
                 <input type="text" value={config.title} onChange={handleTitleChange} className={controlClass} />
            </div>
            <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                     <label className="block text-xs font-medium text-text-secondary">Chart Type</label>
                     <select value={config.chartType} onChange={handleChartTypeChange} className={controlClass}>
                        <option value="bar">Bar</option>
                        <option value="line">Line</option>
                        <option value="area">Area</option>
                        <option value="pie">Pie</option>
                        <option value="scatter">Scatter</option>
                        <option value="composed">Composed</option>
                        <option value="stackedBar">Stacked Bar</option>
                     </select>
                </div>
                <div className="space-y-1">
                     <label className="block text-xs font-medium text-text-secondary">{config.chartType === 'pie' ? 'Label' : 'X-Axis'}</label>
                     <select value={config.nameKey} onChange={handleXAxisChange} className={controlClass}>
                         {xAxisOptions.map(col => <option key={col} value={col}>{col}</option>)}
                     </select>
                </div>
            </div>

            <div className="space-y-1">
                <label className="block text-xs font-medium text-text-secondary">{isMultiSeries ? 'Y-Axis Series' : (config.chartType === 'pie' ? 'Value' : 'Y-Axis')}</label>
                {isMultiSeries ? (
                    <div className="p-2 border border-input rounded-md bg-card max-h-32 overflow-y-auto space-y-1">
                        {numericColumns.map(col => (
                            <label key={col} className="flex items-center text-sm font-medium text-text-secondary p-1 rounded-md hover:bg-black/5 cursor-pointer">
                                <input
                                    type="checkbox"
                                    value={col}
                                    checked={config.dataKeys.includes(col)}
                                    onChange={handleMultiYAxisChange}
                                    className="h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary mr-2"
                                />
                                {col}
                            </label>
                        ))}
                    </div>
                ) : (
                    <select value={config.dataKeys?.[0] || ''} onChange={handleYAxisChange} className={controlClass} disabled={numericColumns.length === 0}>
                        {numericColumns.length === 0 && <option>No numeric columns</option>}
                        {numericColumns.map(col => <option key={col} value={col}>{col}</option>)}
                    </select>
                )}
            </div>
        </div>
    );
};

const ExportDropdown: React.FC<{
  activeTab: Tab;
  onExportCsv: () => void;
  onPrintInsights: () => void;
  onExportChart: (format: 'png' | 'svg') => void;
  disabled: boolean;
}> = ({ activeTab, onExportCsv, onPrintInsights, onExportChart, disabled }) => {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const createMenuItem = (label: string, icon: React.ReactNode, action: () => void) => (
        <button
            onClick={() => { action(); setIsOpen(false); }}
            className="w-full text-left flex items-center px-3 py-2 text-sm text-text hover:bg-black/5 rounded-md"
        >
            {icon}
            <span className="ml-2">{label}</span>
        </button>
    );

    const renderMenuItems = () => {
        switch(activeTab) {
            case 'table': 
                return createMenuItem('Export as CSV', <FileText size={16} />, onExportCsv);
            case 'insights': 
                return createMenuItem('Print / Save as PDF', <Printer size={16} />, onPrintInsights);
            case 'chart': 
                return (
                    <>
                        {createMenuItem('Export as PNG', <FileImage size={16} />, () => onExportChart('png'))}
                        {createMenuItem('Export as SVG', <FileImage size={16} />, () => onExportChart('svg'))}
                    </>
                );
            default: return null;
        }
    };

    return (
        <div ref={dropdownRef} className="relative">
            <button
                onClick={() => setIsOpen(!isOpen)}
                disabled={disabled}
                className="flex items-center px-3 py-1.5 text-xs font-semibold rounded-full transition-all duration-200 border border-border text-text-secondary hover:text-text hover:bg-black/5 disabled:opacity-40 disabled:cursor-not-allowed"
            >
                <FileDown size={14} />
                <span className="ml-1.5">Export</span>
            </button>
            {isOpen && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-card backdrop-blur-2xl border border-white/20 rounded-lg shadow-xl p-1.5 z-20 animate-scale-in">
                    {renderMenuItems()}
                </div>
            )}
        </div>
    );
}


const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ turn, onGenerateInsights, onGenerateChart }) => {
  const { analysisResult, insightsResult, chartResult, insightsLoading, chartLoading } = turn;
  const data = analysisResult?.data || [];
  const sqlResult = analysisResult?.sqlResult;

  const [activeTab, setActiveTab] = useState<Tab>('table');
  const [currentPage, setCurrentPage] = useState(1);
  const [editableChartConfig, setEditableChartConfig] = useState<ChartGenerationResult | null>(null);

  const prevTurnRef = useRef<ConversationTurn | null>(null);
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const insightsContainerRef = useRef<HTMLDivElement>(null);

  const uniqueId = useId();
  const barShadowId = `bar-shadow-${uniqueId}`;
  const lineShadowId = `line-shadow-${uniqueId}`;
  const areaGradientId = `area-gradient-${uniqueId}`;

  useEffect(() => {
    setEditableChartConfig(turn.chartResult?.chartConfig || null);
  }, [turn.chartResult]);

  useEffect(() => {
    const prevTurn = prevTurnRef.current;

    const justGotData = !prevTurn?.analysisResult && !!turn.analysisResult;
    const justGotInsights = !prevTurn?.insightsResult && !!turn.insightsResult;
    const justGotChart = !prevTurn?.chartResult?.chartConfig && !!turn.chartResult?.chartConfig;

    if (justGotChart) {
        setActiveTab('chart');
    } else if (justGotInsights) {
        setActiveTab('insights');
    } else if (justGotData) {
        setActiveTab('table');
    }

    if (turn.analysisResult !== prevTurn?.analysisResult) {
        setCurrentPage(1);
    }

    prevTurnRef.current = turn;
  }, [turn]);

  const hasInsights = !!insightsResult && insightsResult.insights !== "No insights generated.";
  const hasChart = chartResult?.chartConfig !== null && chartResult?.chartConfig !== undefined;

  const { numericColumns, categoricalColumns, allColumns } = useMemo(() => {
        if (!data || data.length === 0) {
            return { numericColumns: [], categoricalColumns: [], allColumns: [] };
        }
        const numeric: string[] = [];
        const categorical: string[] = [];
        const all = Object.keys(data[0]);
        for (const header of all) {
            // Robust check for numeric columns that handles null/undefined
            const isNumeric = data.every(row => {
                const val = row[header];
                return val === null || val === undefined || typeof val === 'number';
            });
            if (isNumeric) {
                numeric.push(header);
            } else {
                categorical.push(header);
            }
        }
        return { numericColumns: numeric, categoricalColumns: categorical, allColumns: all };
    }, [data]);

  const handleExportCsv = () => {
      if (!data || data.length === 0) return;

      const headers = Object.keys(data[0]);
      const csvRows = [
          headers.join(','),
          ...data.map(row =>
              headers.map(fieldName => JSON.stringify(row[fieldName], (_, value) => value === null ? '' : value)).join(',')
          )
      ];
      const csvString = csvRows.join('\r\n');
      const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.setAttribute('href', url);
      a.setAttribute('download', 'query_results.csv');
      a.style.visibility = 'hidden';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
  };

  const handlePrintInsights = () => {
      if (!insightsContainerRef.current) return;
      const contentToPrint = insightsContainerRef.current.innerHTML;
      const printWindow = window.open('', '_blank');

      if (printWindow) {
          printWindow.document.write(`
              <html>
                  <head>
                      <title>ClaroDB Insights</title>
                      <style>
                          body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; line-height: 1.6; color: #1D2129; padding: 2rem; }
                          .print-header { margin-bottom: 1rem; padding-bottom: 1rem; border-bottom: 1px solid #e1e4e8; }
                          .print-header h1 { font-size: 1.5rem; margin: 0; }
                          .print-header p { font-size: 0.9rem; color: #5A6474; margin: 0.25rem 0 0; }
                          h1, h2, h3, h4, h5, h6 { color: #1D2129; font-weight: 600; }
                          ul, ol { padding-left: 20px; }
                          li { margin-bottom: 0.5rem; }
                          strong, b { font-weight: 600; color: #1D2129; }
                          code { font-family: monospace; background-color: #f6f8fa; padding: 0.2em 0.4em; margin: 0; font-size: 85%; border-radius: 6px; }
                      </style>
                  </head>
                  <body>
                      <div class="print-header">
                        <h1>Query Insights</h1>
                        <p>For question: "${turn.question}"</p>
                      </div>
                      ${contentToPrint}
                  </body>
              </html>
          `);
          printWindow.document.close();
          printWindow.focus();
          printWindow.print();
          printWindow.close();
      }
  };

  const handleExportChart = (format: 'png' | 'svg') => {
      if (!chartContainerRef.current) return;
      const svgElement = chartContainerRef.current.querySelector('svg');
      if (!svgElement) return;

      const title = editableChartConfig?.title || 'chart';
      const filename = title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      const a = document.createElement('a');

      // Dynamically get background color to ensure theme consistency.
      const bgElement = document.querySelector('.animated-bg-canvas');
      const bgColor = bgElement ? getComputedStyle(bgElement).backgroundColor : '#F9FAFB'; // Fallback color

      if (format === 'svg') {
          let svgString = new XMLSerializer().serializeToString(svgElement);
          const bgRect = `<rect width="100%" height="100%" fill="${bgColor}"></rect>`;
          // Inject the background rectangle after the opening svg tag
          svgString = svgString.replace(/<svg(.*?)>/, `<svg$1>${bgRect}`);

          const blob = new Blob([svgString], { type: 'image/svg+xml' });
          const url = URL.createObjectURL(blob);
          a.href = url;
          a.download = `${filename}.svg`;
          a.click();
          URL.revokeObjectURL(url);
      } else { // png
          const svgString = new XMLSerializer().serializeToString(svgElement);
          const canvas = document.createElement('canvas');
          const scale = 2; // For higher resolution
          const width = svgElement.clientWidth || 500;
          const height = svgElement.clientHeight || 400;

          canvas.width = width * scale;
          canvas.height = height * scale;

          const ctx = canvas.getContext('2d');
          if (!ctx) return;

          ctx.scale(scale, scale);

          const img = new Image();
          const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
          const url = URL.createObjectURL(svgBlob);

          img.onload = () => {
              ctx.fillStyle = bgColor;
              ctx.fillRect(0, 0, width, height);
              ctx.drawImage(img, 0, 0);
              URL.revokeObjectURL(url);

              const pngUrl = canvas.toDataURL('image/png');
              a.href = pngUrl;
              a.download = `${filename}.png`;
              a.click();
          };
          img.src = url;
      }
  };

  const renderChart = () => {
    if (chartLoading) {
      return <div className="text-center py-8 text-text-secondary flex items-center justify-center min-h-[384px]"><Loader2 size={20} className="animate-spin mr-2" /> Generating chart...</div>;
    }

    // A chart has been successfully generated and is ready to be displayed.
    if (editableChartConfig && data && data.length > 0) {
      const { chartType, dataKeys, nameKey, title, composedTypes } = editableChartConfig;

      // Safety check: ensure required keys exist in data before rendering
      const hasValidKeys = dataKeys.every(k => k in data[0]) && nameKey in data[0];
      if (!hasValidKeys) {
           return <div className="text-center py-8 text-text-secondary min-h-[384px] flex items-center justify-center">Chart configuration mismatch. Please regenerate.</div>;
      }

      return (
        <div className="w-full bg-card/80 backdrop-blur-xl border border-white/20 rounded-xl shadow-card">
          <div className="px-4 py-2 border-b border-black/5">
            <MetadataDisplay
                label="Chart Generation"
                model={chartResult!.model}
                cost={chartResult!.cost}
                prompt_tokens={chartResult!.prompt_tokens}
                completion_tokens={chartResult!.completion_tokens}
            />
          </div>
          <ChartControls
            config={editableChartConfig}
            setConfig={setEditableChartConfig}
            numericColumns={numericColumns}
            categoricalColumns={categoricalColumns}
            allColumns={allColumns}
          />
          <div className="h-96 w-full p-4" ref={chartContainerRef}>
              <h4 className="text-center font-semibold mb-4 text-text">{title}</h4>
              <ResponsiveContainer width="100%" height="100%">
                {(() => {
                  const tickProps = { fontSize: 11, fill: '#5A6474', dy: 5 };
                  switch (chartType) {
                    case 'bar':
                      return (
                        <BarChart data={data} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                          <defs>
                            <filter id={barShadowId} x="-20%" y="-20%" width="140%" height="140%">
                               <feDropShadow dx="0" dy="2" stdDeviation="2" floodColor={PALETTE[0]} floodOpacity="0.3"/>
                            </filter>
                          </defs>
                          <CartesianGrid stroke="rgba(0,0,0,0.05)" vertical={false} />
                          <XAxis dataKey={nameKey} tickLine={false} axisLine={false} tick={tickProps} />
                          <YAxis tickLine={false} axisLine={false} tick={tickProps} />
                          <Tooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(0,0,0,0.04)', radius: 8 }}/>
                          <Legend wrapperStyle={{fontSize: "12px"}} />
                          <Bar dataKey={dataKeys[0]} fill={PALETTE[0]} radius={[6, 6, 0, 0]} style={{ filter: `url(#${barShadowId})` }}/>
                        </BarChart>
                      );
                     case 'stackedBar':
                          return (
                            <BarChart data={data} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                              <CartesianGrid stroke="rgba(0,0,0,0.05)" vertical={false} />
                              <XAxis dataKey={nameKey} tickLine={false} axisLine={false} tick={tickProps} />
                              <YAxis tickLine={false} axisLine={false} tick={tickProps} />
                              <Tooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(0,0,0,0.04)', radius: 8 }}/>
                              <Legend wrapperStyle={{fontSize: "12px"}}/>
                              {dataKeys.map((key, i) => (
                                  <Bar key={key} dataKey={key} stackId="a" fill={PALETTE[i % PALETTE.length]} radius={i === dataKeys.length - 1 ? [6, 6, 0, 0] : [0,0,0,0]} />
                              ))}
                            </BarChart>
                          );
                    case 'line':
                      return (
                        <LineChart data={data} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                             <defs>
                                <filter id={lineShadowId} x="-50%" y="-50%" width="200%" height="200%">
                                    <feDropShadow dx="0" dy="3" stdDeviation="3" floodColor={PALETTE[0]} floodOpacity="0.4"/>
                                </filter>
                            </defs>
                            <CartesianGrid stroke="rgba(0,0,0,0.05)" vertical={false} />
                            <XAxis dataKey={nameKey} tickLine={false} axisLine={false} tick={tickProps} />
                            <YAxis tickLine={false} axisLine={false} tick={tickProps} />
                            <Tooltip content={<CustomTooltip />} cursor={{ stroke: PALETTE[0], strokeWidth: 1, strokeDasharray: "4 4" }}/>
                            <Legend wrapperStyle={{fontSize: "12px"}}/>
                            <Line type="monotone" dataKey={dataKeys[0]} stroke={PALETTE[0]} strokeWidth={2.5} dot={false} activeDot={{ r: 6, stroke: '#fff', strokeWidth: 2, fill: PALETTE[0] }} style={{ filter: `url(#${lineShadowId})` }}/>
                        </LineChart>
                      );
                    case 'area':
                          return (
                            <AreaChart data={data} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                               <defs>
                                <linearGradient id={areaGradientId} x1="0" y1="0" x2="0" y2="1">
                                  <stop offset="5%" stopColor={PALETTE[0]} stopOpacity={0.4}/>
                                  <stop offset="95%" stopColor={PALETTE[0]} stopOpacity={0.05}/>
                                </linearGradient>
                                <filter id={lineShadowId} x="-50%" y="-50%" width="200%" height="200%">
                                  <feDropShadow dx="0" dy="3" stdDeviation="3" floodColor={PALETTE[0]} floodOpacity="0.4"/>
                                </filter>
                              </defs>
                              <CartesianGrid stroke="rgba(0,0,0,0.05)" vertical={false} />
                              <XAxis dataKey={nameKey} tickLine={false} axisLine={false} tick={tickProps} />
                              <YAxis tickLine={false} axisLine={false} tick={tickProps} />
                              <Tooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(0,0,0,0.04)', radius: 8 }}/>
                              <Legend wrapperStyle={{fontSize: "12px"}}/>
                              <Area type="monotone" dataKey={dataKeys[0]} stroke={PALETTE[0]} strokeWidth={2.5} fill={`url(#${areaGradientId})`} dot={false} activeDot={{ r: 6, stroke: '#fff', strokeWidth: 2, fill: PALETTE[0] }} style={{ filter: `url(#${lineShadowId})` }} />
                            </AreaChart>
                          );
                    case 'composed':
                          return (
                              <ComposedChart data={data} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                                  <CartesianGrid stroke="rgba(0,0,0,0.05)" vertical={false} />
                                  <XAxis dataKey={nameKey} tickLine={false} axisLine={false} tick={tickProps} />
                                  <YAxis tickLine={false} axisLine={false} tick={tickProps} />
                                  <Tooltip content={<CustomTooltip />} />
                                  <Legend wrapperStyle={{fontSize: "12px"}}/>
                                  {dataKeys.map((key, i) => {
                                      const type = composedTypes?.[i] || 'bar';
                                      const color = PALETTE[i % PALETTE.length];
                                      switch (type) {
                                          case 'line': return <Line key={key} type="monotone" dataKey={key} stroke={color} strokeWidth={2.5} dot={false} activeDot={{ r: 6, stroke: '#fff', strokeWidth: 2, fill: color }} />;
                                          case 'area': return <Area key={key} type="monotone" dataKey={key} fill={color} stroke={color} fillOpacity={0.6} dot={false} activeDot={{ r: 6, stroke: '#fff', strokeWidth: 2, fill: color }} />;
                                          default: return <Bar key={key} dataKey={key} fill={color} radius={[6, 6, 0, 0]} />;
                                      }
                                  })}
                              </ComposedChart>
                          );
                    case 'pie':
                      return (
                        <PieChart>
                          <Pie 
                            data={data} 
                            dataKey={dataKeys[0]} 
                            nameKey={nameKey} 
                            cx="50%" 
                            cy="50%" 
                            outerRadius={'80%'}
                            innerRadius={'60%'}
                            stroke="#F8F9FC"
                            strokeWidth={3}
                            paddingAngle={3}
                            cornerRadius={8}
                          >
                            {data.map((entry, index) => <Cell key={`cell-${index}`} fill={PALETTE[index % PALETTE.length]} />)}
                          </Pie>
                          <Tooltip content={<CustomTooltip />} />
                          <Legend wrapperStyle={{fontSize: "12px"}}/>
                        </PieChart>
                      );
                    default:
                        return <div className="text-center py-8 text-text-secondary">Unsupported chart type: {chartType}</div>;
                  }
                })()}
              </ResponsiveContainer>
          </div>
        </div>
      );
    }

    // Handle all other states (initial, failed, no data).
    const hasAttempted = chartResult !== undefined;
    const hasData = data && data.length > 0;

    let content: React.ReactNode;

    if (!hasData) {
      content = <div className="text-center py-8 text-text-secondary min-h-[384px] flex items-center justify-center">No data available to generate a chart.</div>;
    } else if (hasAttempted) { // Attempted but failed (since editableChartConfig is null)
      content = <div className="text-center py-8 text-text-secondary min-h-[384px] flex items-center justify-center">Chart could not be generated for this query.</div>;
    } else { // Not attempted yet, initial state.
      content = (
        <div className="text-center py-8 text-text-secondary flex flex-col items-center justify-center gap-3 min-h-[384px]">
          <BarChart2 size={24} />
          <span>Click the "Generate Chart" button to visualize these results.</span>
        </div>
      );
    }

    return (
      <div className="bg-secondary-background rounded-lg border border-border">
        {/* Show metadata only if an attempt was made and failed */}
        {hasAttempted && !editableChartConfig && chartResult && (
          <div className="px-4 py-2 border-b border-border">
            <MetadataDisplay
              label="Chart Generation"
              model={chartResult.model}
              cost={chartResult.cost}
              prompt_tokens={chartResult.prompt_tokens}
              completion_tokens={chartResult.completion_tokens}
            />
          </div>
        )}
        {content}
      </div>
    );
  };

  const headers = useMemo(() => (data && data.length > 0 ? Object.keys(data[0]) : []), [data]);

  const totalPages = data ? Math.ceil(data.length / ROWS_PER_PAGE) : 0;
  const paginatedData = useMemo(() => {
    if (!data) return [];
    const startIndex = (currentPage - 1) * ROWS_PER_PAGE;
    const endIndex = startIndex + ROWS_PER_PAGE;
    return data.slice(startIndex, endIndex);
  }, [data, currentPage]);

  const renderContent = () => {
    switch(activeTab) {
      case 'table':
        return data.length > 0 ? (
           <div className="overflow-x-auto border border-border rounded-lg bg-card/80 backdrop-blur-xl shadow-card">
              <table className="w-full text-sm text-left">
                  <thead className="bg-white/30">
                      <tr>
                          {headers.map(h => <th key={h} className="px-4 py-3 font-semibold text-text">{h}</th>)}
                      </tr>
                  </thead>
                  <tbody>
                      {paginatedData.map((row, i) => (
                          <tr key={i} className="border-t border-black/5 even:bg-white/20">
                              {headers.map(h => <td key={h} className="px-4 py-3 text-text-secondary truncate max-w-xs">{String(row[h])}</td>)}
                          </tr>
                      ))}
                  </tbody>
              </table>
               {totalPages > 1 && (
                  <div className="flex justify-between items-center p-2 border-t border-black/5 text-xs text-text-secondary">
                      <button onClick={() => setCurrentPage(p => p - 1)} disabled={currentPage === 1} className="px-2 py-1 rounded-md disabled:opacity-50 hover:bg-black/5 flex items-center transition-colors">
                        <ChevronLeft size={14} className="mr-1" /> Prev
                      </button>
                      <span>Page {currentPage} of {totalPages}</span>
                      <button onClick={() => setCurrentPage(p => p + 1)} disabled={currentPage === totalPages} className="px-2 py-1 rounded-md disabled:opacity-50 hover:bg-black/5 flex items-center transition-colors">
                        Next <ChevronRight size={14} className="ml-1" />
                      </button>
                  </div>
              )}
          </div>
        ) : (
          <div className="text-center py-8 text-text-secondary">The query returned no results.</div>
        );
      case 'insights':
        if (insightsLoading) {
            return <div className="text-center py-8 text-text-secondary flex items-center justify-center"><Loader2 size={20} className="animate-spin mr-2" /> Generating insights...</div>;
        }

        if (insightsResult) {
            return (
                <div className="bg-card/80 backdrop-blur-xl border border-white/20 rounded-xl shadow-card">
                    <div className="px-4 py-2 border-b border-black/5">
                        <MetadataDisplay
                            label="Insight Generation"
                            model={insightsResult.model}
                            cost={insightsResult.cost}
                            prompt_tokens={insightsResult.prompt_tokens}
                            completion_tokens={insightsResult.completion_tokens}
                        />
                    </div>
                    <div ref={insightsContainerRef} className="prose prose-sm max-w-none p-6 text-text prose-headings:text-text prose-strong:text-text">
                        <ReactMarkdown>{insightsResult.insights}</ReactMarkdown>
                    </div>
                </div>
            );
        }

        if (data.length === 0) {
            return (
                <div className="bg-secondary-background rounded-lg border border-border">
                    <div className="text-center py-8 text-text-secondary">
                        No data available to generate insights.
                    </div>
                </div>
            );
        }

        return (
            <div className="bg-secondary-background rounded-lg border border-border">
                <div className="text-center py-8 text-text-secondary flex flex-col items-center gap-3">
                    <Lightbulb size={24} />
                    <span>Click the "Generate Insight Summary" button to get an AI-powered analysis.</span>
                </div>
            </div>
        );
      case 'chart':
        return renderChart();
      default:
        return null;
    }
  }

  const isExportDisabled = (activeTab === 'table' && data.length === 0) || (activeTab === 'insights' && !hasInsights) || (activeTab === 'chart' && !hasChart);

  return (
    <div className="space-y-4">
      {sqlResult && (
        <div className="pb-3 border-b border-border">
            <MetadataDisplay
                label="SQL Generation"
                model={sqlResult.model}
                cost={sqlResult.cost}
                prompt_tokens={sqlResult.prompt_tokens}
                completion_tokens={sqlResult.completion_tokens}
            />
        </div>
      )}
      <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex space-x-1 p-1 bg-secondary-background rounded-full border border-border">
            <TabButton icon={<Table size={16} />} label="Table" isActive={activeTab === 'table'} onClick={() => setActiveTab('table')} />
            <TabButton icon={<Lightbulb size={16} />} label="Insights" isActive={activeTab === 'insights'} onClick={() => setActiveTab('insights')} />
            <TabButton icon={<BarChart2 size={16} />} label="Chart" isActive={activeTab === 'chart'} onClick={() => setActiveTab('chart')} />
          </div>
          <div className="flex items-center space-x-4">
            {!hasInsights && activeTab === 'insights' && (
                <button onClick={() => onGenerateInsights(turn.id)} disabled={insightsLoading || data.length === 0} className="text-xs font-semibold text-primary hover:text-primary/80 disabled:opacity-50 flex items-center">
                    {insightsLoading && <Loader2 size={14} className="animate-spin mr-1.5" />}
                    Generate Insight Summary
                </button>
            )}
            {!hasChart && activeTab === 'chart' && (
                <button onClick={() => onGenerateChart(turn.id)} disabled={chartLoading || data.length === 0} className="text-xs font-semibold text-primary hover:text-primary/80 disabled:opacity-50 flex items-center">
                    {chartLoading && <Loader2 size={14} className="animate-spin mr-1.5" />}
                    Generate Chart
                </button>
            )}
             <ExportDropdown
                activeTab={activeTab}
                onExportCsv={handleExportCsv}
                onPrintInsights={handlePrintInsights}
                onExportChart={handleExportChart}
                disabled={isExportDisabled}
             />
          </div>
      </div>
      <div className="animate-fade-in-up">{renderContent()}</div>
    </div>
  );
};

interface TabButtonProps {
    icon: React.ReactNode;
    label: string;
    isActive: boolean;
    onClick: () => void;
    disabled?: boolean;
}

const TabButton: React.FC<TabButtonProps> = ({ icon, label, isActive, onClick, disabled = false }) => {
    return (
        <button
            onClick={onClick}
            disabled={disabled}
            className={`flex items-center px-4 py-1.5 text-sm font-medium rounded-full transition-all duration-200 disabled:opacity-40 disabled:cursor-not-allowed ${
                isActive 
                ? 'text-primary-foreground bg-primary shadow-sm' 
                : 'text-text-secondary hover:text-text hover:bg-black/5'
            }`}
        >
            {icon}
            <span className="ml-2">{label}</span>
        </button>
    )
}

export default ResultsDisplay;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { TableSchema, Join, Point, ConversationTurn } from '../types';
import { Loader2, AlertTriangle, Bot, MessageSquare, User } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import ConversationTurnDisplay from './ConversationTurnDisplay';
import InteractiveSchemaCard from './InteractiveSchemaCard';
import JoinLines from './JoinLines';
import CanvasToolbar from './CanvasToolbar';
import ChatInput from './ChatInput';
import { useAppContext } from '../contexts/AppContext';

interface DataModelingCanvasProps {
    isLoading: boolean;
    loadingText: string;
    pageError?: string | null;
    schemas: TableSchema | null;
    tableNameMap: Record<string, string>;
    cardPositions: Record<string, Point>;
    setCardPositions: React.Dispatch<React.SetStateAction<Record<string, Point>>>;
    joins: Join[];
    onOpenJoinModal: (details: Omit<Join, 'id' | 'joinType'>) => void;
    conversation: ConversationTurn[];
    onExecuteSql: (turnId: string, sql: string) => void;
    onGenerateInsights: (turnId: string) => void;
    onGenerateChart: (turnId: string) => void;
    question: string;
    setQuestion: (q: string) => void;
    onSend: () => void;
    isChatDisabled: boolean;
    placeholder: string;
    children: React.ReactNode; // For the left sidebar content
}

const DataModelingCanvas: React.FC<DataModelingCanvasProps> = ({
    isLoading,
    loadingText,
    pageError,
    schemas,
    tableNameMap,
    cardPositions,
    setCardPositions,
    joins,
    onOpenJoinModal,
    conversation,
    onExecuteSql,
    onGenerateInsights,
    onGenerateChart,
    question,
    setQuestion,
    onSend,
    isChatDisabled,
    placeholder,
    children,
}) => {
    const { resultsPanelWidth, setResultsPanelWidth } = useAppContext();
    const [joinSource, setJoinSource] = useState<{table: string, column: string} | null>(null);
    const [joinTarget, setJoinTarget] = useState<{table: string, column: string} | null>(null);
    const [drawingLine, setDrawingLine] = useState<{start: Point, end: Point} | null>(null);
    const [draggedTable, setDraggedTable] = useState<string | null>(null);

    const isResizing = useRef(false);

    const canvasRef = useRef<HTMLDivElement>(null);
    const chatContainerRef = useRef<HTMLDivElement>(null);

    // Use refs to hold the latest values for join source/target to avoid stale closures in event listeners
    const joinSourceRef = useRef(joinSource);
    useEffect(() => { joinSourceRef.current = joinSource; }, [joinSource]);
    const joinTargetRef = useRef(joinTarget);
    useEffect(() => { joinTargetRef.current = joinTarget; }, [joinTarget]);

    const compatibleTargets = useMemo(() => {
        if (!joinSource) return new Set<string>();
        const targets = new Set<string>();
        if (schemas) {
            Object.keys(schemas).forEach((tableName) => {
                const columns = schemas[tableName];
                if (tableName !== joinSource.table) {
                    columns.forEach(col => targets.add(`${tableName}-${col.name}`));
                }
            });
        }
        return targets;
    }, [joinSource, schemas]);

    // Optimize active join columns calculation to prevent unnecessary re-renders of all cards
    // The calculation only depends on joins and drag state.
    const activeJoinColumns = useMemo(() => {
        return new Set<string>(joins.flatMap(j => 
            (j.table1 === draggedTable || j.table2 === draggedTable) 
            ? [`${j.table1}-${j.column1}`, `${j.table2}-${j.column2}`] 
            : []
        ));
    }, [joins, draggedTable]);

    useEffect(() => {
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTo({ 
                top: chatContainerRef.current.scrollHeight, 
                behavior: 'smooth' 
            });
        }
    }, [conversation]);

    const handleMouseMove = useCallback((e: MouseEvent) => {
        if (!joinSourceRef.current || !canvasRef.current) return;
        const canvasRect = canvasRef.current.getBoundingClientRect();
        const startEl = document.getElementById(`col-${joinSourceRef.current.table}-${joinSourceRef.current.column}`);
        if (!startEl) return;

        const startRect = startEl.getBoundingClientRect();
        const start = {
            x: startRect.left + startRect.width - canvasRect.left + canvasRef.current.scrollLeft,
            y: startRect.top + startRect.height / 2 - canvasRect.top + canvasRef.current.scrollTop,
        };
        const end = {
            x: e.clientX - canvasRect.left + canvasRef.current.scrollLeft,
            y: e.clientY - canvasRect.top + canvasRef.current.scrollTop,
        };
        setDrawingLine({ start, end });
    }, []);

    const handleMouseUp = useCallback(() => {
        if (joinTargetRef.current && joinSourceRef.current) {
            if (joinSourceRef.current.table !== joinTargetRef.current.table) {
                onOpenJoinModal({
                    table1: joinSourceRef.current.table,
                    column1: joinSourceRef.current.column,
                    table2: joinTargetRef.current.table,
                    column2: joinTargetRef.current.column,
                });
            }
        }
        setJoinSource(null);
        setDrawingLine(null);
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
    }, [onOpenJoinModal]);

    const handleColumnMouseDown = useCallback((table: string, column: string) => {
        setJoinSource({ table, column });
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
    }, [handleMouseMove, handleMouseUp]);

    const handleCardDrag = useCallback((tableName: string, newPosition: Point) => {
      setCardPositions(prev => ({ ...prev, [tableName]: newPosition }));
    }, [setCardPositions]);

    const handleAutoLayout = () => {
        if (!schemas || Object.keys(schemas).length === 0) return;

        const tableNames = Object.keys(schemas);
        const cardWidth = 288;
        const cardHeight = 280;
        const padding = 60;
        const canvasWidth = canvasRef.current?.clientWidth || 1000;

        const adjList = new Map<string, string[]>();
        tableNames.forEach(name => adjList.set(name, []));
        joins.forEach(join => {
            adjList.get(join.table1)?.push(join.table2);
            adjList.get(join.table2)?.push(join.table1);
        });

        const components: string[][] = [];
        const visited = new Set<string>();
        tableNames.forEach(tableName => {
            if (!visited.has(tableName)) {
                const component: string[] = [];
                const queue: string[] = [tableName];
                visited.add(tableName);
                let head = 0;
                while (head < queue.length) {
                    const u = queue[head++];
                    component.push(u);
                    const neighbors = adjList.get(u);
                    if (Array.isArray(neighbors)) {
                        neighbors.forEach(v => {
                            if (!visited.has(v)) {
                                visited.add(v);
                                queue.push(v);
                            }
                        });
                    }
                }
                components.push(component);
            }
        });

        components.sort((a, b) => b.length - a.length);

        const newPositions: Record<string, Point> = {};
        let cursorX = padding;
        let cursorY = padding;
        let maxRowHeight = 0;

        components.forEach(component => {
            const componentCols = Math.ceil(Math.sqrt(component.length));
            const componentWidth = componentCols * (cardWidth + padding);
            const componentRows = Math.ceil(component.length / componentCols);
            const componentHeight = componentRows * (cardHeight + padding);

            if (cursorX + componentWidth > canvasWidth && cursorX > padding) {
                cursorX = padding;
                cursorY += maxRowHeight;
                maxRowHeight = 0;
            }

            component.forEach((tableName, i) => {
                const row = Math.floor(i / componentCols);
                const col = i % componentCols;
                newPositions[tableName] = {
                    x: cursorX + col * (cardWidth + padding),
                    y: cursorY + row * (cardHeight + padding),
                };
            });

            cursorX += componentWidth;
            if (componentHeight > maxRowHeight) maxRowHeight = componentHeight;
        });

        setCardPositions(newPositions);
    };

    const handleResizeMouseMove = useRef((e: MouseEvent) => {
        if (!isResizing.current) return;
        const leftPanelWidth = 384; // w-96
        const minCanvasWidth = 300; 
        const newWidth = window.innerWidth - e.clientX;

        const maxWidth = window.innerWidth - leftPanelWidth - minCanvasWidth;
        const clampedWidth = Math.max(400, Math.min(newWidth, maxWidth));

        setResultsPanelWidth(clampedWidth);
    }).current; // Stable ref for listener

    const handleResizeMouseUp = useRef(() => {
        isResizing.current = false;
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        document.removeEventListener('mousemove', handleResizeMouseMove);
        document.removeEventListener('mouseup', handleResizeMouseUp);
    }).current; // Stable ref for listener

    const handleResizeMouseDown = useCallback((e: React.MouseEvent) => {
        e.preventDefault();
        isResizing.current = true;
        document.body.style.cursor = 'col-resize';
        document.body.style.userSelect = 'none';
        document.addEventListener('mousemove', handleResizeMouseMove);
        document.addEventListener('mouseup', handleResizeMouseUp);
    }, [handleResizeMouseMove, handleResizeMouseUp]);

    // Cleanup listeners on unmount
    useEffect(() => {
        return () => {
            document.removeEventListener('mousemove', handleResizeMouseMove);
            document.removeEventListener('mouseup', handleResizeMouseUp);
        };
    }, [handleResizeMouseMove, handleResizeMouseUp]);

    return (
        <div className="flex flex-col h-full bg-transparent overflow-hidden">
            <div className="flex-1 flex overflow-hidden">
                <aside className="w-96 flex-shrink-0 bg-secondary-background/50 border-r border-border flex flex-col relative z-20">
                    {children}
                </aside>

                <main className="flex-1 relative overflow-hidden z-10">
                    <div ref={canvasRef} className="h-full w-full overflow-auto relative bg-dot-grid">
                        {isLoading && <div className="absolute inset-0 z-30 bg-white/50 flex justify-center items-center"><Loader2 className="animate-spin text-primary" size={24} /><span className="ml-2 text-text-secondary">{loadingText}</span></div>}
                        {pageError && (
                            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 w-full max-w-md p-4">
                                <div className="flex items-start text-danger bg-danger/10 p-4 rounded-lg border border-danger/20 shadow-lg">
                                    <AlertTriangle size={20} className="mr-3 flex-shrink-0 mt-0.5" />
                                    <div><h4 className="font-semibold">Error</h4><p className="text-sm mt-1">{pageError}</p></div>
                                </div>
                            </div>
                        )}

                        {schemas && (
                            <>
                                <JoinLines
                                    joins={joins}
                                    drawingLine={drawingLine}
                                    hoveredJoinId={null}
                                    cardPositions={cardPositions}
                                    draggedTable={draggedTable}
                                />
                                {Object.keys(schemas).map((tableName) => (
                                    <InteractiveSchemaCard
                                        key={tableName}
                                        tableName={tableName}
                                        displayName={tableNameMap[tableName] || tableName}
                                        schema={schemas[tableName]}
                                        position={cardPositions[tableName]}
                                        onDrag={handleCardDrag}
                                        onDragStart={setDraggedTable}
                                        onDragEnd={() => setDraggedTable(null)}
                                        onColumnMouseDown={handleColumnMouseDown}
                                        onColumnMouseUp={() => {}}
                                        onColumnEnter={setJoinTarget}
                                        onColumnLeave={() => setJoinTarget(null)}
                                        isSource={joinSource?.table === tableName}
                                        sourceColumn={joinSource?.column}
                                        compatibleTargets={compatibleTargets}
                                        activeJoinColumns={activeJoinColumns}
                                    />
                                ))}
                                <CanvasToolbar onAutoLayout={handleAutoLayout} />
                            </>
                        )}
                    </div>
                </main>

                {conversation.length > 0 && (
                    <aside className="flex-shrink-0 flex animate-scale-in z-30" style={{ width: `${resultsPanelWidth}px` }}>
                        <div onMouseDown={handleResizeMouseDown} className="w-1.5 h-full cursor-col-resize bg-border/50 hover:bg-primary transition-colors duration-200"></div>
                        <div className="flex flex-col flex-1 bg-secondary-background/50 border-l border-border overflow-hidden">
                            <div className="p-4 border-b border-border">
                                <h2 className="text-lg font-semibold text-text flex items-center"><MessageSquare size={18} className="mr-2 text-primary" /> Query Results</h2>
                            </div>
                            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8">
                                <div className="space-y-8">
                                    {conversation.map((turn) => (
                                        <React.Fragment key={turn.id}>
                                            <div className="flex items-start justify-end group"><div className="bg-primary text-primary-foreground rounded-xl rounded-br-none p-4 max-w-2xl shadow-md"><p>{turn.question}</p></div><div className="w-10 h-10 rounded-full bg-primary/10 text-primary flex items-center justify-center ml-3 flex-shrink-0"><User size={20} /></div></div>
                                            <div className="flex items-start group"><div className="w-10 h-10 rounded-full bg-background text-primary border border-border flex items-center justify-center mr-3 flex-shrink-0"><Bot size={20} /></div><div className="flex-1 min-w-0"><ConversationTurnDisplay turn={turn} onExecute={onExecuteSql} onGenerateInsights={onGenerateInsights} onGenerateChart={onGenerateChart} /></div></div>
                                        </React.Fragment>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </aside>
                )}
            </div>

            <div className="flex-shrink-0 z-40">
                <ChatInput value={question} onChange={setQuestion} onSend={onSend} isLoading={isChatDisabled} placeholder={placeholder} disabled={isChatDisabled}/>
            </div>
        </div>
    );
};

export default DataModelingCanvas;
